    private static final String SHA=VettingCorpus.hash("authored pdf source"),NOTE="(1) EXACT_COMPLETE_NOTE_DEFINITION;",BODY="1. FIELD VALUE Note (1)";
    @Test void actualSavedNoteNineSuffixReachesTheRealAnchorOrdinaryModelAndLosslessWire() throws Exception {
        SourceDocument source=actualCom11NoteNine(true);JsonNode graph=NormalSourceCandidateGraph.requireBound(source),anchor=actualCom11Method(graph,19,"camelot_stream");
        assertEquals(1,anchor.path("methodContinuationObservations").size(),"Actual saved Note9 suffix must belong to the real table anchor");assertEquals(19,anchor.path("sourcePosition").path("physicalPageNo").asInt());assertEquals(JsonUtils.parse("[19,20]"),anchor.path("physicalPageNos"));
        JsonNode suffix=anchor.path("methodContinuationObservations").get(0);assertFalse(suffix.path("nativeGlyphNamespacesJoined").asBoolean(true));assertEquals(3,suffix.path("ordinaryNativeBlockIds").size());
        String closure="For other areas, abbreviation to be proposed by the Main Contractor for CMR's agreement.";assertTrue(suffix.toString().contains(closure));
        for(JsonNode id:suffix.path("ordinaryNativeBlockIds"))assertTrue(strings(anchor.path("requiredMemberBlockIds")).contains(id.asText()));
        JsonNode edge=suffix.path("relations").get(0);assertEquals("source_order",edge.path("direction").asText());assertEquals(9,edge.path("guards").path("lastExplicitNoteNumber").asInt());assertEquals("unknown",edge.path("legalApplicability").asText());
        List<DocumentBlock> blocks=VettingCorpus.blocks(source);DocumentBlock next=blocks.stream().filter(b->b.getPageNo()!=null&&b.getPageNo()==20&&b.getNativeTableCandidate()!=null&&"camelot_stream".equals(b.getNativeTableCandidate().path("method").asText())).findFirst().orElseThrow();assertTrue(next.getNativeTableCandidate().path("candidate").path("logicalTables").isEmpty(),"No next-page table may be invented");
        VettingCorpus.Chunk seed=hit(source,anchor.path("bodyBlockIds").get(0).asText());JsonNode model=new OerModelMaterial.Request(Collections.singletonList(source)).projectOrdinary(seed);JsonNode unit=null;for(JsonNode value:methodUnits(model.path("units")))if(value.path("group").path("id").equals(anchor.path("id")))unit=value;assertNotNull(unit);assertTrue(unit.toString().contains(closure));assertFalse(unit.path("semanticScopeVerified").asBoolean(true));assertFalse(unit.path("humanConfirmed").asBoolean(true));assertEquals("unknown",unit.path("legalClosure").asText());
        JsonNode material=JsonUtils.parse(JsonUtils.write(VettingSourceMaterial.project(Collections.singletonList(seed),Collections.singletonList(source))));assertTrue(material.toString().contains(closure));assertEquals(JsonUtils.write(material),JsonUtils.write(VettingSourceMetadataWire.decode(VettingSourceMetadataWire.write(material))));
    }
    @Test void actualSavedFacadeAndVolumetricAndAllSamePageNoteDefinitionsRemainExact() throws Exception {
        SourceDocument old=actualCom11NoteNine(false),changed=actualCom11NoteNine(true);JsonNode baseline=NormalSourceCandidateGraph.requireBound(old),candidate=NormalSourceCandidateGraph.requireBound(changed);
        for(int page:new int[]{15,19,24,29,33})for(String method:Arrays.asList("camelot_stream","camelot_network")){
            JsonNode before=actualCom11Method(baseline,page,method),after=actualCom11Method(candidate,page,method);assertEquals(before.path("methodTable"),after.path("methodTable"),"Existing full table values and blanks stay exact");assertEquals(before.path("methodObservation"),after.path("methodObservation"),"All original same-page notes and relations stay exact");assertFalse(after.path("semanticScopeVerified").asBoolean(true));
            if(page==15||page==33)assertTrue(after.path("methodContinuationObservations").isMissingNode());
        }
    }
    @Test void actualSavedSuffixWrongSourceRawReverseEdgeAndAmbiguousNativeLineCannotExpandTheAnchor() throws Exception {
        for(int kind=0;kind<4;kind++){
            SourceDocument source=actualCom11NoteNine(true);List<DocumentBlock> blocks=VettingCorpus.blocks(source);DocumentBlock carrier=blocks.stream().filter(b->b.getPageNo()!=null&&b.getPageNo()==20&&b.getNativeTableCandidate()!=null&&"camelot_stream".equals(b.getNativeTableCandidate().path("method").asText())).findFirst().orElseThrow();ObjectNode raw=(ObjectNode)carrier.getNativeTableCandidate(),continuation=(ObjectNode)raw.path("candidate").path("observationGroups").path("continuations");
            if(kind==0)continuation.put("sourceSha256",VettingCorpus.hash("different original"));if(kind==1)((ObjectNode)continuation.path("anchorRawRef")).put("sha256",VettingCorpus.hash("different saved method"));if(kind==2)((ObjectNode)continuation.path("groups").get(0).path("relations").get(0)).put("direction","reverse");
            if(kind==3){DocumentBlock original=blocks.stream().filter(b->b.getPageNo()!=null&&b.getPageNo()==20&&b.getEffectiveText().contains("For other areas")).findFirst().orElseThrow();DocumentBlock duplicate=JsonUtils.read(JsonUtils.write(original),DocumentBlock.class);duplicate.setId(original.getId()+":duplicate-source-line");blocks.add(duplicate);}
            source.setStructuredContentJson(JsonUtils.write(blocks));NormalSourceCandidateGraph.capture(source);JsonNode graph=NormalSourceCandidateGraph.requireBound(source),anchor=actualCom11Method(graph,19,"camelot_stream");assertTrue(anchor.path("methodContinuationObservations").isMissingNode(),"Unsafe suffix must not be attached, case "+kind);assertFalse(graph.path("nativePdfSourceGroups").path("issues").isEmpty());assertFalse(anchor.path("semanticScopeVerified").asBoolean(true));
        }
    }
    private static SourceDocument actualCom11NoteNine(boolean updated) throws Exception {
        String value=System.getProperty("consense.sl.note9.fixture",System.getenv("CONSENSE_SL_NOTE9_FIXTURE"));org.junit.jupiter.api.Assumptions.assumeTrue(value!=null&&!value.isBlank(),"Explicit actual saved COM11 fixture required");Path root=Path.of(value).toRealPath();byte[] compressed=Files.readAllBytes(root.resolve("saved-normal.json.gz"));assertEquals("6c8f8f80baf36dbfeb7b7268aec115dd844511b3396708f41eb2e11f713dc979",String.format("%064x",new BigInteger(1,MessageDigest.getInstance("SHA-256").digest(compressed))));JsonNode normal;try(GZIPInputStream stream=new GZIPInputStream(new java.io.ByteArrayInputStream(compressed))){normal=JsonUtils.mapper().readTree(stream);}ObjectNode parsed=(ObjectNode)normal.path("parsedDocument");ArrayNode blocks=parsed.path("blocks").deepCopy();
        if(updated){String output=System.getProperty("consense.sl.note9.replay",System.getenv("CONSENSE_SL_NOTE9_REPLAY_OUTPUT"));assertNotNull(output,"Root must freeze the actual Python saved-provider replay before Java RED/GREEN");Path directory=Path.of(output).toRealPath();byte[] bytes=Files.readAllBytes(directory.resolve("actual-native-candidate-replay.json"));JsonNode pin=JsonUtils.parse(Files.readString(directory.resolve("actual-native-candidate-replay.pin.json")));assertEquals(pin.path("bytes").asLong(),bytes.length);assertEquals(pin.path("sha256").asText(),String.format("%064x",new BigInteger(1,MessageDigest.getInstance("SHA-256").digest(bytes))));JsonNode reply=JsonUtils.parse(new String(bytes,StandardCharsets.UTF_8));assertEquals(parsed.path("sourceSha256"),reply.path("source").path("sourceSha256"));
            for(JsonNode page:reply.path("pages"))for(JsonNode method:page.path("methods")){int number=page.path("physicalPageNo").asInt();JsonNode target=null;for(JsonNode block:blocks)if(block.path("pageNo").asInt()==number&&block.path("nativeTableCandidate").path("method").equals(method.path("method"))){assertNull(target);target=block;}assertNotNull(target);ObjectNode observed=method.deepCopy();observed.put("physicalPageNo",number);observed.set("frame",page.path("frame").deepCopy());observed.set("coverage",reply.path("coverage").deepCopy());observed.set("bundleRef",reply.path("bundleRef").deepCopy());observed.set("sourceObservationRef",page.path("sourceObservationRef").deepCopy());observed.set("nativeGlyphNamespace",page.path("nativeGlyphNamespace").deepCopy());observed.set("sourceSha256",reply.path("source").path("sourceSha256").deepCopy());observed.put("semanticStatus","candidate_unverified");((ObjectNode)target).set("nativeTableCandidate",observed);}
        }
        SourceDocument source=new SourceDocument();source.setId(901L);source.setProjectId("actual-saved-com11-note9");source.setCategory(SourceDocument.CATEGORY_VETTING_PACKAGE);source.setReviewRole("tender");source.setFileKey("SL");source.setFileName("SL_architectural_COM11_complete-section.pdf");source.setSourceSha256(parsed.path("sourceSha256").asText());source.setParseStatus(parsed.path("parseStatus").asText());source.setPageCount(55);source.setTextContent(parsed.path("text").asText());source.setStructuredContentJson(JsonUtils.write(blocks));source.setParseCoverageJson(JsonUtils.write(parsed.path("coverage")));NormalSourceCandidateGraph.capture(source);return source;
    }
    private static JsonNode actualCom11Method(JsonNode graph,int page,String method){JsonNode result=null;for(JsonNode group:graph.path("nativePdfSourceGroups").path("groups"))if("native_table_method_group".equals(group.path("kind").asText())&&group.path("methodBinding").path("physicalPageNo").asInt()==page&&method.equals(group.path("methodBinding").path("method").asText())){assertNull(result);result=group;}assertNotNull(result,"Actual saved method group required: "+page+"/"+method);assertFalse(result.path("bodyBlockIds").isEmpty());return result;}
    @Test void bodySeedClosesWholeNotesForEveryIndependentAlignedMethodWithoutChangingQuote(){
        SourceDocument source=source(true);VettingCorpus.Chunk hit=hit(source,"row");assertTrue(hit.getParts().stream().noneMatch(p->p.getNativeTableCandidate()!=null));String before=JsonUtils.write(hit);
        List<JsonNode> groups=methodGroups(hit.getCandidateStructure().path("nativePdfSourceGroups").path("groups"));assertEquals(2,groups.size(),"A native body seed must close each independent uniquely aligned source method group");Set<String> methods=new HashSet<>();
        for(JsonNode group:groups){methods.add(group.path("methodBinding").path("method").asText());assertTrue(group.path("scopeComplete").asBoolean());assertTrue(JsonUtils.write(group.path("methodObservation")).contains(NOTE));assertEquals(4,group.path("methodTable").path("origins").size());assertEquals("",group.path("methodTable").path("origins").get(3).path("text").asText());assertFalse(group.path("semanticScopeVerified").asBoolean());assertEquals("unknown",group.path("legalClosure").asText());}
        assertEquals(new HashSet<>(Arrays.asList("camelot_stream","camelot_network")),methods);assertEquals(before,JsonUtils.write(hit));
    }
    @Test void completeMethodTableBlanksAndNotesReachOrdinaryModelAndLosslessWireAsUnrankedContext(){
        SourceDocument source=source(false);VettingCorpus.Chunk hit=hit(source,"row");String before=JsonUtils.write(hit);OerModelMaterial.Request request=new OerModelMaterial.Request(Collections.singletonList(source));JsonNode model=request.projectOrdinary(hit);assertNotNull(model,"PDF body seeds require the same bound ordinary source-context path");
        List<JsonNode> units=methodUnits(model.path("units"));assertEquals(1,units.size());JsonNode unit=units.get(0);assertTrue(JsonUtils.write(unit).contains(NOTE));assertTrue(unit.path("parts").isEmpty());assertTrue(unit.path("sourceSpans").isEmpty());assertFalse(unit.path("semanticScopeVerified").asBoolean());assertFalse(unit.path("humanConfirmed").asBoolean());assertEquals("unknown",unit.path("legalClosure").asText());
        JsonNode material=JsonUtils.parse(JsonUtils.write(VettingSourceMaterial.project(Collections.singletonList(hit),Collections.singletonList(source))));assertTrue(JsonUtils.write(material).contains(NOTE));assertTrue(JsonUtils.write(material).equals(JsonUtils.write(VettingSourceMetadataWire.decode(VettingSourceMetadataWire.write(material)))),"Complete ordered source/model JSON must roundtrip exactly");assertTrue(request.projectOrdinary(hit).path("units").get(0).has("modelUnitRef"));assertEquals(before,JsonUtils.write(hit));
    }
    @Test void wrongOriginalFramePageTextCasDuplicateGroupsAndRepeatedNotesStayUnknown(){
        for(int kind=0;kind<18;kind++){
            SourceDocument source=source(false);List<DocumentBlock> blocks=VettingCorpus.blocks(source);JsonNode method=blocks.stream().filter(b->b.getNativeTableCandidate()!=null).findFirst().get().getNativeTableCandidate();ObjectNode raw=(ObjectNode)method,table=(ObjectNode)raw.path("candidate").path("logicalTables").get(0);
            if(kind==0)raw.put("sourceSha256",VettingCorpus.hash("foreign pdf"));if(kind==1)((ObjectNode)raw.path("candidate")).put("sourceSha256",VettingCorpus.hash("foreign candidate"));if(kind==2)((ObjectNode)raw.path("frame")).put("pageWidth",101);if(kind==3){((ObjectNode)raw.path("frame")).put("rotation",90);((ObjectNode)raw.path("candidate").path("frame")).put("rotation",90);}if(kind==4)raw.put("physicalPageNo",2);if(kind==5)raw.remove("rawRef");if(kind==6)((ObjectNode)table.path("origins").get(0)).put("text","DIFFERENT SOURCE TEXT");
            if(kind==7)((ArrayNode)raw.path("candidate").path("observationGroups").path("groups")).add(raw.path("candidate").path("observationGroups").path("groups").get(0).deepCopy());
            if(kind==8){ObjectNode group=(ObjectNode)raw.path("candidate").path("observationGroups").path("groups").get(0);ObjectNode duplicate=group.path("members").get(0).deepCopy();duplicate.put("memberId","repeated-notes");((ArrayNode)group.path("members")).add(duplicate);}
            ObjectNode observedGroup=(ObjectNode)raw.path("candidate").path("observationGroups").path("groups").get(0),edge=(ObjectNode)observedGroup.path("relations").get(0),note=(ObjectNode)observedGroup.path("members").get(0);
            if(kind==9)note.put("text",NOTE+"\n(1) DIFFERENT_BODY_WITH_SAME_NUMBER;");if(kind==10)note.put("text","(2) SOURCE_HAS_NO_NOTE_ONE_DEFINITION;");if(kind==11)edge.put("status","ambiguous_definition");if(kind==12)((ArrayNode)observedGroup.path("relations")).removeAll();if(kind==13)((ObjectNode)edge.path("toCell")).put("row",99);if(kind==14)edge.putArray("definitionGlyphIds").add(999);if(kind==15){((ObjectNode)table.path("origins").get(1)).put("text","NO_CALLOUT");((ArrayNode)observedGroup.path("relations")).removeAll();DocumentBlock row=blocks.stream().filter(b->"row".equals(b.getId())).findFirst().orElseThrow();String changed="1. FIELD VALUE NO_CALLOUT";row.setText(changed);row.setOriginalText(changed);row.getPdfGlyphs().get(0).setUnicode(changed);source.setTextContent(source.getTextContent().replace(BODY,changed));}
            if(kind==16){((ObjectNode)raw.path("frame")).put("rotation",.5);((ObjectNode)raw.path("candidate").path("frame")).put("rotation",.5);}if(kind==17){((ObjectNode)raw.path("frame")).put("rotation",false);((ObjectNode)raw.path("candidate").path("frame")).put("rotation",false);}
            source.setStructuredContentJson(JsonUtils.write(blocks));NormalSourceCandidateGraph.capture(source);assertTrue(JsonUtils.write(NormalSourceCandidateGraph.requireBound(source)).contains("candidateSourceSha256"));VettingCorpus.Chunk hit=hit(source,"row");assertTrue(methodGroups(hit.getCandidateStructure().path("nativePdfSourceGroups").path("groups")).isEmpty(),"Unsafe independent method context must not expand, case "+kind);assertFalse(hit.getCandidateStructure().path("nativePdfSourceGroups").path("issues").isEmpty(),"Failed alignment/provenance must remain explicit unknown, case "+kind);
        }
    }
