    @Test void duplicateNativeBlockIdsKeepOrdinarySeedsAndMarkOnlyTheNewContextUnknown(){
        SourceDocument source=source(false);List<DocumentBlock> blocks=VettingCorpus.blocks(source);blocks.add(nativeLine("duplicate-native",2,.1,.10,"9. First duplicate source observation"));blocks.add(nativeLine("duplicate-native",2,.1,.30,"10. Second duplicate source observation"));source.setPageCount(2);source.setStructuredContentJson(JsonUtils.write(blocks));NormalSourceCandidateGraph.capture(source);
        JsonNode graph=NormalSourceCandidateGraph.requireBound(source);assertTrue(graph.path("units").toString().contains("missing_or_duplicate_actual_block_id"));
        List<VettingCorpus.Chunk> chunks=assertDoesNotThrow(()->VettingCorpus.chunks(Collections.singletonList(source)),"An unrelated duplicate identity must not erase the readable ordinary corpus");VettingCorpus.Chunk seed=chunks.stream().filter(c->c.getParts().stream().anyMatch(p->"row".equals(p.getBlockId()))).findFirst().orElseThrow();String before=JsonUtils.write(seed);JsonNode context=seed.getCandidateStructure().path("nativePdfSourceGroups");
        assertTrue(seed.getContent().contains(BODY));assertTrue(seed.getCandidateStructure().path("units").toString().contains(BODY));assertTrue(context.path("groups").isEmpty());assertTrue(context.path("members").isEmpty());assertTrue(context.path("issues").toString().contains("pdf_source_block_identity_duplicate"));
        assertTrue(chunks.stream().anyMatch(c->c.getParts().stream().anyMatch(p->"duplicate-native".equals(p.getBlockId()))));assertTrue(chunks.stream().filter(c->c.getParts().stream().anyMatch(p->"duplicate-native".equals(p.getBlockId()))).allMatch(c->c.getCandidateStructure().path("unknowns").toString().contains("ambiguous_actual_member_identity_prevents_unit_expansion")),"The existing duplicate-unit unknown guard must remain in force");
        JsonNode model=assertDoesNotThrow(()->new OerModelMaterial.Request(Collections.singletonList(source)).projectOrdinary(seed));assertNotNull(model);assertTrue(model.path("units").isEmpty());assertTrue(model.path("unknowns").toString().contains("pdf_source_block_identity_duplicate"));assertDoesNotThrow(()->VettingSourceMaterial.project(Collections.singletonList(seed),Collections.singletonList(source)));assertEquals(before,JsonUtils.write(seed));
    }
    @Test void singleRootChildAndWidgetSeedsKeepWithinParentRelationsAndExactNoteTargets(){
        SourceDocument source=syntaxSource();JsonNode graph=NormalSourceCandidateGraph.requireBound(source);String stored=JsonUtils.write(graph);
        for(String id:Arrays.asList("two","b","margin")){
            VettingCorpus.Chunk seed=singleSeed(source,id);String quotation=JsonUtils.write(seed);JsonNode context=seed.getCandidateStructure().path("nativePdfSourceGroups");
            JsonNode root=sourceGroup(context,"source_clause","2"),child=sourceGroup(context,"source_clause","2(b)"),note=sourceGroup(context,"source_margin_note","2(b)");assertTrue(root.path("scopeComplete").asBoolean());assertEquals(Arrays.asList("b","reference"),strings(note.path("bodyBlockIds")));assertEquals(child.path("id"),note.path("parentId"));
            JsonNode noteEdge=sourceRelation(context,"source_explicit_note_target");assertEquals(child.path("id"),noteEdge.path("targetGroupId"));assertFalse(noteEdge.path("targetIncludesDescendants").asBoolean());assertEquals(Arrays.asList("b","reference"),strings(noteEdge.path("targetBlockIds")));assertEquals("exact_observed_node_only",noteEdge.path("targetScope").asText());
            assertTrue(strings(root.path("bodyBlockIds")).containsAll(Arrays.asList("two","a","b","reference","inspection","hours")));assertTrue(context.path("members").findValues("blockId").stream().noneMatch(n->"three".equals(n.asText())));assertTrue(context.path("groups").findValues("reference").stream().noneMatch(n->"3".equals(n.asText())));
            if(!"margin".equals(id)){assertEquals(5,context.path("groups").size());assertEquals(Arrays.asList("inspection","hours"),strings(sourceGroup(context,"parent_tail","2:tail1").path("bodyBlockIds")));assertNotNull(sourceRelation(context,"source_parent"));assertNotNull(sourceRelation(context,"source_parent_tail"));assertEquals(2,countSourceRelations(context,"source_literal_reference"));}
            else{assertEquals(3,context.path("groups").size(),"A widget adds its exact target and complete reading ancestors, without recursively selecting sibling/descendant metadata");assertTrue(context.path("groups").findValues("kind").stream().noneMatch(n->"parent_tail".equals(n.asText())));}
            JsonNode ordinary=new OerModelMaterial.Request(Collections.singletonList(source)).projectOrdinary(seed);assertNotNull(ordinary);assertEquals(context.path("relations"),ordinary.path("sourceGroupRelations"));assertEquals(context.path("groups").size(),ordinary.path("units").size());assertEquals(quotation,JsonUtils.write(seed));assertEquals(stored,JsonUtils.write(NormalSourceCandidateGraph.requireBound(source)));
        }
    }
