    @Test void canonicalModelUsesTheSameGroupManifestAndRejectsForeignRevisionBindings() throws Exception {
        SourceDocument source=source(false);JsonNode graph=NormalSourceCandidateGraph.requireBound(source);EvidencePointer pointer=modelPointer(source,graph,"row");ObjectNode member=canonicalMember(graph,"row");JsonNode context=pointer.getNativePdfSourceGroupsContext();assertNotNull(context);String before=JsonUtils.write(pointer);
        JsonNode model=new OerModelMaterial.Request().project(pointer,member,"tender");assertEquals(context.path("groups").get(0),model.path("observedSourceGroups").get(0).path("group"));assertEquals(context.path("relations"),model.path("sourceGroupRelations"));assertTrue(JsonUtils.write(model).contains(NOTE));assertFalse(model.path("observedSourceGroups").get(0).path("humanConfirmed").asBoolean());assertEquals("unknown",model.path("observedSourceGroups").get(0).path("legalClosure").asText());assertTrue(JsonUtils.write(model).equals(JsonUtils.write(VettingSourceMetadataWire.decode(VettingSourceMetadataWire.write(model)))),"Complete ordered canonical model JSON must roundtrip exactly");assertEquals(before,JsonUtils.write(pointer));
        for(String key:Arrays.asList("projectId","documentId","parsedSourceHash","originalSourceSha256","sourceRevisionSha256","projectionSha256")){
            EvidencePointer changed=JsonUtils.read(before,EvidencePointer.class);ObjectNode changedContext=(ObjectNode)changed.getNativePdfSourceGroupsContext();if(Arrays.asList("projectId","documentId","parsedSourceHash").contains(key))((ObjectNode)changedContext.path("source")).put(key,"different-bound-source");else changedContext.put(key,VettingCorpus.hash("other revision"));
            IllegalArgumentException failure=assertThrows(IllegalArgumentException.class,()->new OerModelMaterial.Request().project(changed,member,"tender"));assertTrue(failure.getMessage().contains("normal_pdf_source_group_context_binding_differs"),key);
        }
    }
    @Test void selectedIssuesKeepLocalPageFailuresWhileCompleteInventoryRetainsOtherPages(){
        SourceDocument source=source(false);List<DocumentBlock> blocks=VettingCorpus.blocks(source);DocumentBlock remote=nativeLine("remote-invalid",2,.1,.1,"9. Remote observation");remote.getPdfGlyphs().get(0).setCoordinateSpace("unknown_remote_frame");blocks.add(remote);source.setPageCount(2);source.setStructuredContentJson(JsonUtils.write(blocks));NormalSourceCandidateGraph.capture(source);JsonNode graph=NormalSourceCandidateGraph.requireBound(source);assertTrue(graph.path("nativePdfSourceGroups").path("issues").toString().contains("remote-invalid"));JsonNode context=singleSeed(source,"row").getCandidateStructure().path("nativePdfSourceGroups");assertFalse(context.path("issues").toString().contains("remote-invalid"));assertTrue(context.path("issues").toString().contains("row"),"Native line syntax unknowns on the selected page remain visible");
    }
    private static VettingCorpus.Chunk singleSeed(SourceDocument source,String id){VettingCorpus.Chunk seed=hit(source,id);VettingCorpus.Part part=seed.getParts().stream().filter(p->id.equals(p.getBlockId())).findFirst().orElseThrow();seed.setParts(Collections.singletonList(part));seed.setContent(part.getText());seed.setCandidateStructure(NormalSourceCandidateGraph.selected(NormalSourceCandidateGraph.requireBound(source),seed));return seed;}
    private static SourceDocument syntaxSource(){SourceDocument source=source(false);List<DocumentBlock> blocks=new ArrayList<>(Arrays.asList(nativeLine("two",1,.10,.10,"2. Documents not issued:"),nativeLine("a",1,.15,.15,"(a) Available documents."),nativeLine("b",1,.15,.20,"(b) Other drawings."),nativeLine("reference",1,.17,.22,"See condition 2(a); also condition 3."),nativeLine("inspection",1,.115,.25,"These documents may be inspected"),nativeLine("hours",1,.115,.27,"during normal office hours."),nativeLine("three",1,.10,.32,"3. Separate reference target")));DocumentBlock form=nativeLine("margin",1,.02,.20,"See Special Conditions");form.setKind("pdf_form_widget");form.setSource("native_form");form.getPdfGlyphs().clear();PdfPageEvidence.PdfFormField field=new PdfPageEvidence.PdfFormField();field.setId("pdf-form/margin/widget/0");field.setFieldName("Clause2b");field.setFieldValue(form.getText());field.setAppearanceValue(form.getText());field.setPageNo(1);field.setAppearancePresent(true);field.setAppearanceGlyphObservationStatus("observed_existing_normal_AP_operators_unreviewed");PdfPageEvidence.PdfGlyph glyph=new PdfPageEvidence.PdfGlyph();glyph.setId(field.getId()+"/glyph/0");glyph.setUnicode(form.getText());glyph.setCoordinateSpace("appearance_stream_local_matrix_no_page_box");glyph.setTextMatrix(new double[]{8,0,0,8,2,20});glyph.setEligibleForNativeText(true);field.getAppearanceGlyphs().add(glyph);form.setPdfFormField(field);blocks.add(form);source.setTextContent(String.join("\n",blocks.stream().map(DocumentBlock::getText).toArray(String[]::new)));source.setStructuredContentJson(JsonUtils.write(blocks));ObjectNode coverage=(ObjectNode)JsonUtils.parse(source.getParseCoverageJson());coverage.putArray("failedPages");source.setParseCoverageJson(JsonUtils.write(coverage));NormalSourceCandidateGraph.capture(source);return source;}
    private static DocumentBlock nativeLine(String id,int page,double x,double y,String text){DocumentBlock block=new DocumentBlock();block.setId(id);block.setKind("pdf_line");block.setSource("native");block.setLocation("pdf-page/"+page+"/line/"+id);block.setPageNo(page);block.setText(text);block.setOriginalText(text);block.setBbox(new double[]{x,y,text.codePointCount(0,text.length())*.005,.01});ObjectNode context=JsonUtils.mapper().createObjectNode();context.put("sourceSha256",SHA);block.setReadingContext(context);int offset=0,n=0;while(offset<text.length()){int point=text.codePointAt(offset);String value=new String(Character.toChars(point));PdfPageEvidence.PdfGlyph glyph=new PdfPageEvidence.PdfGlyph();glyph.setId("pdf-page/"+page+"/glyph/"+id+"/"+n);glyph.setUnicode(value);glyph.setCoordinateSpace("normalized_rendered_crop_top_left");glyph.setEligibleForNativeText(true);glyph.setBbox(new double[]{x+n*.005,y,.005,.01});glyph.setTextMatrix(new double[]{10,0,0,10,(x+n*.005)*1000,(1-y)*1000});glyph.setFontSize(10);glyph.setFontSizeInPt(10);glyph.setPdfboxPosition(new double[]{0,0,0,0,0,0,0,0,1000,1000});block.getPdfGlyphs().add(glyph);offset+=value.length();n++;}return block;}
    private static ObjectNode canonicalMember(JsonNode graph,String id){for(JsonNode unit:graph.path("units"))for(JsonNode part:unit.path("parts"))if(id.equals(part.path("blockId").asText())){ObjectNode member=unit.deepCopy();member.put("producerKind",NormalObservedContract.PRODUCER).put("id","canonical:authored-model");member.putArray("relations");member.putArray("assetRefs");member.putArray("eligibleModules").add("advisory");member.putObject("sourceQuality");return member;}throw new AssertionError(id);}
    private static EvidencePointer modelPointer(SourceDocument source,JsonNode graph,String id) throws Exception {CanonicalSourceBinding binding=new CanonicalSourceBinding();binding.setProjectId(source.getProjectId());binding.setDocumentId(source.getId());binding.setOriginalSourceSha256(source.getSourceSha256());binding.setJavaParsedSourceHash(VettingCorpus.sourceHash(source));binding.setCanonicalSourceHash(VettingCorpus.hash("canonical-source"));binding.setSourceRevisionSha256(VettingCorpus.hash("source-revision"));binding.setProjectionSha256(VettingCorpus.hash("projection"));binding.setProjectionRevisionSha256(VettingCorpus.hash("projection-revision"));ObjectNode snapshot=JsonUtils.mapper().createObjectNode();snapshot.put("schema",NormalObservedContract.SCHEMA);snapshot.putObject("manifest").set("candidateGraph",graph);snapshot.putObject("source").put("sourceFilename","authored.pdf");snapshot.putArray("unknowns");Method method=CanonicalEvidenceService.class.getDeclaredMethod("pointer",CanonicalSourceBinding.class,JsonNode.class,JsonNode.class,String.class);method.setAccessible(true);return (EvidencePointer)method.invoke(null,binding,snapshot,canonicalMember(graph,id),"advisory");}
    private static JsonNode sourceGroup(JsonNode context,String kind,String ref){for(JsonNode group:context.path("groups"))if(kind.equals(group.path("kind").asText())&&ref.equals(group.path("reference").asText()))return group;throw new AssertionError(kind+":"+ref+" "+context);}
    private static JsonNode sourceRelation(JsonNode context,String type){for(JsonNode relation:context.path("relations"))if(type.equals(relation.path("type").asText()))return relation;throw new AssertionError(type);}
    private static int countSourceRelations(JsonNode context,String type){int n=0;for(JsonNode relation:context.path("relations"))if(type.equals(relation.path("type").asText()))n++;return n;}
    private static List<String> strings(JsonNode values){List<String> out=new ArrayList<>();values.forEach(v->out.add(v.asText()));return out;}
    private static List<JsonNode> methodGroups(JsonNode values){List<JsonNode> out=new ArrayList<>();for(JsonNode value:values)if("native_table_method_group".equals(value.path("kind").asText()))out.add(value);return out;}
    private static List<JsonNode> methodUnits(JsonNode values){List<JsonNode> out=new ArrayList<>();for(JsonNode value:values)if("ordinary_native_pdf_source_group".equals(value.path("kind").asText())&&"native_table_method_group".equals(value.path("group").path("kind").asText()))out.add(value);return out;}
    static VettingCorpus.Chunk hit(SourceDocument source,String block){return VettingCorpus.chunks(Collections.singletonList(source)).stream().filter(c->c.getParts().stream().anyMatch(p->block.equals(p.getBlockId()))).findFirst().orElseThrow(()->new AssertionError(block));}
    static SourceDocument source(boolean twoMethods){
        SourceDocument source=new SourceDocument();source.setId(90L);source.setProjectId("authored-native-pdf");source.setCategory(SourceDocument.CATEGORY_VETTING_PACKAGE);source.setReviewRole("tender");source.setFileKey("SL");source.setFileName("authored.pdf");source.setSourceSha256(SHA);source.setParseStatus("PARSED");source.setPageCount(1);
        List<DocumentBlock> blocks=new ArrayList<>();blocks.add(line("row",BODY,.2));blocks.add(line("filler-a",String.join("",Collections.nCopies(1360,"A")),.7));blocks.add(line("outside","UNRELATED SAME PAGE NOTE (1)",.8));blocks.add(line("filler-b",String.join("",Collections.nCopies(1340,"B")),.9));blocks.add(line("separator",String.join("",Collections.nCopies(1401,"C")),.95));blocks.add(method("camelot_stream"));if(twoMethods)blocks.add(method("camelot_network"));
        source.setTextContent(String.join("\n",Arrays.asList(BODY,"UNRELATED SAME PAGE NOTE (1)")));source.setStructuredContentJson(JsonUtils.write(blocks));ObjectNode coverage=JsonUtils.mapper().createObjectNode();coverage.put("totalPages",1).put("parsedPages",1).put("ocrPages",0).put("complete",true).put("ocrQualityPageScopeUnknown",false);coverage.putArray("needsReviewPages");source.setParseCoverageJson(JsonUtils.write(coverage));NormalSourceCandidateGraph.capture(source);return source;
    }
    private static DocumentBlock line(String id,String text,double y){DocumentBlock b=new DocumentBlock();b.setId(id);b.setKind("pdf_line");b.setLocation("pdf-page/1/line/"+id);b.setPageNo(1);b.setSource("native");b.setText(text);b.setOriginalText(text);b.setBbox(new double[]{.1,y,.7,.03});ObjectNode context=JsonUtils.mapper().createObjectNode();context.put("sourceSha256",SHA);context.put("occurrenceId",id);b.setReadingContext(context);PdfPageEvidence.PdfGlyph g=new PdfPageEvidence.PdfGlyph();g.setId("pdf-page/1/glyph/"+id);g.setUnicode(text);g.setEligibleForNativeText(true);g.setBbox(b.getBbox());g.setPdfboxPosition(new double[]{10,y*100,70,3,10,y*100,70,3,100,100});g.setClippingBoundsPdf(new double[]{0,0,100,100});b.setPdfGlyphs(Collections.singletonList(g));return b;}
    private static DocumentBlock method(String name){
        DocumentBlock b=new DocumentBlock();b.setId("method:"+name);b.setKind("native_table_candidate");b.setLocation("pdf-page/1/native-table-method/"+name);b.setPageNo(1);b.setSource("native_table_candidate");ObjectNode raw=JsonUtils.mapper().createObjectNode();raw.put("provider","camelot").put("method",name).put("status","candidate_observed").put("physicalPageNo",1).put("sourceSha256",SHA).put("nativeGlyphNamespace","pdfplumber/page/1").put("semanticStatus","candidate_unverified");ObjectNode frame=frame();raw.set("frame",frame);descriptor(raw,"rawRef",name,"whole_independent_native_pdf_provider_result");descriptor(raw,"bundleRef","bundle","whole_native_pdf_candidate_bundle");descriptor(raw,"sourceObservationRef","source-observation","actual_native_pdf_source_observation");ObjectNode candidate=raw.putObject("candidate");candidate.put("schema","consense.native-pdf-page-table-candidates.v1").put("method",name).put("provider","camelot").put("physicalPageNo",1).put("sourceSha256",SHA).put("nativeGlyphNamespace","pdfplumber/page/1");candidate.set("frame",frame.deepCopy());candidate.put("completeSourceGroupAccepted",false);String physical=SHA+":1:"+name+":table:0",logical=physical+":logical";ObjectNode table=candidate.putArray("logicalTables").addObject();table.put("tableId",logical).put("providerTableId",physical).put("rowCount",2).put("colCount",2).put("completeTableGroupAccepted",false);table.set("bbox",JsonUtils.mapper().valueToTree(new double[]{10,18,90,40}));ArrayNode origins=table.putArray("origins");origin(origins,0,0,"1. FIELD VALUE",10,65);origin(origins,0,1,"Note (1)",65,90);origin(origins,1,0,"2. OPTIONAL",10,65);origin(origins,1,1,"",65,90);ObjectNode physicalTable=candidate.putArray("tables").addObject();physicalTable.put("tableId",physical);physicalTable.set("cells",origins.deepCopy());ObjectNode group=candidate.putObject("observationGroups").putArray("groups").addObject();group.put("tableId",logical).put("wholeSourceGroupAccepted",false);ObjectNode note=group.putArray("members").addObject();note.put("memberId",logical+":notes").put("role","complete_adjacent_notes_context_proposal").put("text",NOTE);note.set("bbox",JsonUtils.mapper().valueToTree(new double[]{10,50,90,60}));note.putArray("glyphIds").add(1).add(2);ObjectNode relation=group.putArray("relations").addObject();relation.put("type","note_applies_to").put("fromMemberId",logical+":notes").put("sourceNoteMarker",1).put("sourceMarkerExpression","Note (1)").put("status","same_page_unique_explicit_marker_definition");relation.putArray("definitionGlyphIds").add(1).add(2);relation.putObject("toCell").put("tableId",logical).put("row",0).put("col",1);group.putArray("unknown").add("method_structure_not_source_reviewed");b.setNativeTableCandidate(raw);return b;
    }
